CREATE FUNCTION public.create_interview(payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; aid uuid; sid uuid; BEGIN IF NOT public.can_edit_workspace() THEN RAISE EXCEPTION 'Only analysts and admins create interviews'; END IF; PERFORM pg_advisory_xact_lock(710112026); INSERT INTO public.job_roles(title,department) VALUES(payload->>'title','Job analysis') RETURNING id INTO rid; INSERT INTO public.role_analysis_versions(job_role_id,version_number) VALUES(rid,1) RETURNING id INTO aid; INSERT INTO public.interview_sessions(job_role_id,analysis_version_id,purposes,role_state,incumbents,locations,source_types,custom_output) VALUES(rid,aid,ARRAY(SELECT jsonb_array_elements_text(payload->'purposes')),payload->>'role_state',(payload->>'incumbents')::integer,payload->>'locations',ARRAY(SELECT jsonb_array_elements_text(payload->'source_types')),coalesce(payload->>'custom_output','')) RETURNING id INTO sid; RETURN sid; END $$;
CREATE FUNCTION public.save_interview_answer(payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.interview_sessions; src public.interview_sources; eid uuid; aid uuid; oldanswer record; cid uuid; v jsonb; BEGIN PERFORM pg_advisory_xact_lock(710112026); SELECT * INTO s FROM public.interview_sessions WHERE id=(payload->>'session_id')::uuid FOR UPDATE; SELECT * INTO src FROM public.interview_sources WHERE id=(payload->>'source_id')::uuid AND session_id=s.id; IF s.id IS NULL OR src.id IS NULL THEN RAISE EXCEPTION 'Analysis or source not found'; END IF; IF NOT public.can_edit_workspace() AND NOT (public.has_role(auth.uid(),'contributor') AND src.user_id=auth.uid()) THEN RAISE EXCEPTION 'Not permitted to answer for this source'; END IF; IF s.status<>'draft' THEN RAISE EXCEPTION 'Interview is frozen during review and after approval'; END IF; v:=payload->'values'; INSERT INTO public.evidence_items(job_role_id,code,title,source_type,excerpt,source_reference) VALUES(s.job_role_id,'JA-'||substr(gen_random_uuid()::text,1,8),payload->>'module'||' interview answers','sme_interview',v::text,src.name||' ('||src.source_type||')') RETURNING id INTO eid; INSERT INTO public.interview_answers(session_id,source_id,module,values,evidence_id) VALUES(s.id,src.id,payload->>'module',v,eid) RETURNING id INTO aid; IF payload->>'module' IN ('F','H') THEN FOR oldanswer IN SELECT DISTINCT ON (a.source_id) a.* FROM public.interview_answers a WHERE a.session_id=s.id AND a.module=payload->>'module' AND a.source_id<>src.id ORDER BY a.source_id,a.created_at DESC LOOP IF EXISTS(SELECT 1 FROM jsonb_each_text(v) x WHERE length(btrim(x.value))>0 AND length(btrim(coalesce(oldanswer.values->>x.key,'')))>0 AND lower(btrim(x.value))<>lower(btrim(oldanswer.values->>x.key))) THEN INSERT INTO public.evidence_conflicts(job_role_id,topic,description) VALUES(s.job_role_id,payload->>'module'||' source disagreement','Potential disagreement between '||src.name||' and another source. Review the attached evidence; neither source has been selected automatically.') RETURNING id INTO cid; INSERT INTO public.conflict_evidence(conflict_id,evidence_id) VALUES(cid,eid),(cid,oldanswer.evidence_id); END IF; END LOOP; END IF; RETURN aid; END $$;
REVOKE ALL ON FUNCTION public.create_interview(jsonb),public.save_interview_answer(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_interview(jsonb),public.save_interview_answer(jsonb) TO authenticated;
CREATE FUNCTION public.guard_interview_sources_immutable() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Interview sources, answers and outputs are append-only'; END $$;
CREATE TRIGGER answers_immutable BEFORE UPDATE OR DELETE ON public.interview_answers FOR EACH ROW EXECUTE FUNCTION public.guard_interview_sources_immutable(); CREATE TRIGGER sources_immutable BEFORE UPDATE OR DELETE ON public.interview_sources FOR EACH ROW EXECUTE FUNCTION public.guard_interview_sources_immutable(); CREATE TRIGGER outputs_immutable BEFORE UPDATE OR DELETE ON public.interview_outputs FOR EACH ROW EXECUTE FUNCTION public.guard_interview_sources_immutable(); REVOKE ALL ON FUNCTION public.guard_interview_sources_immutable() FROM PUBLIC,anon,authenticated;